    fun loadCoins(ctx: Context, db : SQLiteDatabase): Int {
        val selectQuery = "SELECT * FROM $TABLE_NAME;"
        val cursor = db.rawQuery(selectQuery, null)
        cursor.moveToFirst()
        var result = cursor.getString(2).toInt()
        binding.txtMoedas.text = result.toString()
        cursor.close()
        return result

